namespace gui_forms {

// CommandOverflowPanel's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/command_overflow_panel.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The space between neighbouring groups and before the actuator, finite and between zero and 256 (else std::invalid_argument).
template <typename Declaring>
struct CommandOverflowGroupGapCapability {
    PropertyCell<double, CommandOverflowGroupGapCapability<Declaring>> group_gap{0.0};

    static void assign(CommandOverflowGroupGapCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.group_gap), incoming);
        if (!capability.group_gap.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.group_gap));
    }
};

// Every CommandOverflowPanel capability, in the order the declaring class takes them.
template <typename Declaring>
struct CommandOverflowPanelCapabilities : public CommandOverflowGroupGapCapability<Declaring> {};

} // namespace gui_forms
